functions.inputCaptureStart:
static void inputCaptureStart() {
    // GP-926R17 R17-1：GameBar 订阅在**独立初始化线程**建立（不依赖异常采样/详细日志/前台切换/
    // 唤醒）；失败有界重试。首个 T1 准入前即完成可用性检查。
    gamebarTraceStartInitThread();
    if (g_inputCaptureThread) return;
    if (!applyInputStartupOnce()) {
        writeLog("ERROR", "input startup initialization failed; capture/output held closed");
        publishStartupInputState(ymcc::StartupInputState::Failed, "startup-input-settings-write-failed");
        return;
    }
    if (!inputCaptureAssetsPresent()) {
        writeLog("INFO", "input-capture skipped: no gyro-motion/virtual-gamepad folders");
        publishStartupInputState(ymcc::StartupInputState::Failed, "input-assets-unavailable");
        return;
    }
    g_inputCaptureStop.store(false, std::memory_order_release);
    g_inputCaptureThread = CreateThread(nullptr, 0, inputCaptureThreadProc, nullptr, 0, nullptr);
    if (!g_inputCaptureThread)
        publishStartupInputState(ymcc::StartupInputState::Failed, "capture-thread-create-failed");
}

functions.inputCaptureThreadProc:
static DWORD WINAPI inputCaptureThreadProc(LPVOID) noexcept {
    // R1（2026-09-17 需求单）：tid → 角色映射（一次性）。
    ymccLogThreadRole("capture-worker");
    bool comInitialized = false;
    bool highResolutionTimer = false;
    bool shutdownCompleted = false;
    HANDLE captureTimer = nullptr;
    UINT captureTimerId = 0;
    bool multimediaTimer = false;
    const auto timerEvidenceOwner = g_inputTimerEvidenceNextOwner.fetch_add(1, std::memory_order_relaxed) + 1;
    const char* phase = "delay";
    try {
        // Read-only preference check before the existing worker delay: users
        // with virtual output off must not wait 2.5 s for optional hardware.
        skipDisabledStartupInputGate();
        Sleep(2500);
        if (g_inputCaptureStop.load(std::memory_order_acquire)) {
            publishStartupInputState(ymcc::StartupInputState::Failed, "capture-cancelled-before-init");
            return 0;
        }

        phase = "co-initialize";
        const HRESULT comResult = CoInitializeEx(nullptr, COINIT_MULTITHREADED);
        if (FAILED(comResult)) {
            writeLog("WARN", json({{"event", "input-capture.start-rejected"},
                {"reason", "mta-initialization-failed"}, {"hresult", comResult}}).dump());
            publishStartupInputState(ymcc::StartupInputState::Failed, "capture-com-init-failed");
            return 0;
        }
        comInitialized = true;
        highResolutionTimer = timeBeginPeriod(1) == TIMERR_NOERROR;
        appendNativeLifecycleLog("input-capture-timer-resolution", {
            {"requestedMs", 1},
            {"enabled", highResolutionTimer},
            {"publishIntervalMs", kInputCaptureGamepadPublishIntervalMs}
        });

        // HC drives ControllerManager from PrecisionTimer at its default
        // 8 ms / 125 Hz interval. A loop-tail Sleep(1) is coalesced to the
        // platform timer quantum on this host, producing the observed
        // 15-16 ms cadence. Prefer the multimedia periodic timer used by
        // PrecisionTimer-style implementations; retain waitable timer and
        // Sleep as compatibility fallbacks.
        captureTimer = CreateEventW(nullptr, FALSE, FALSE, nullptr);
        if (captureTimer) {
            g_inputTimerEvidence.ownerBegin(timerEvidenceOwner, GetTickCount64(),
                reinterpret_cast<unsigned long long>(captureTimer),
                static_cast<unsigned>(ymcc::inputTimerEvidence::Kind::multimedia), kInputCaptureGamepadPublishIntervalMs);
            // Drain the complete callback, including prefix and tail outside BUS.
            captureTimerId = timeSetEvent(
                kInputCaptureGamepadPublishIntervalMs, 1, inputCaptureTimerEventProc,
                reinterpret_cast<DWORD_PTR>(captureTimer),
                TIME_PERIODIC | TIME_KILL_SYNCHRONOUS);
            g_inputTimerEvidence.createResult(timerEvidenceOwner, GetTickCount64(),
                reinterpret_cast<unsigned long long>(captureTimer), captureTimerId, captureTimerId ? 0 : TIMERR_NOCANDO);
            multimediaTimer = captureTimerId != 0;
            if (!multimediaTimer) {
                CloseHandle(captureTimer);
                captureTimer = nullptr;
            }
        }
        constexpr DWORD kCreateWaitableTimerHighResolution = 0x00000002;
        if (!captureTimer) captureTimer = CreateWaitableTimerExW(nullptr, nullptr,
            kCreateWaitableTimerHighResolution, TIMER_ALL_ACCESS);
        if (!captureTimer) captureTimer = CreateWaitableTimerW(nullptr, FALSE, nullptr);
        if (captureTimer && !multimediaTimer) {
            LARGE_INTEGER due{};
            due.QuadPart = -static_cast<LONGLONG>(kInputCaptureGamepadPublishIntervalMs) * 10000LL;
            if (!SetWaitableTimer(captureTimer, &due,
                static_cast<LONG>(kInputCaptureGamepadPublishIntervalMs), nullptr, nullptr, FALSE)) {
                CloseHandle(captureTimer);
                captureTimer = nullptr;
            }
        }
        appendNativeLifecycleLog("input-capture-scheduler", {
            {"kind", multimediaTimer ? "multimedia-periodic" :
                (captureTimer ? "waitable-periodic" : "sleep-fallback")},
            {"intervalMs", kInputCaptureGamepadPublishIntervalMs},
            {"highResolutionRequested", true},
            {"dispatch", multimediaTimer ? "direct-timer-callback" : "worker-fallback"},
            {"hcTimerParity", multimediaTimer}
        });

        phase = "capture-init";
        inputCaptureInit();
        // HC creates/connects the selected virtual persona independently of
        // MotionManager. A disabled gyro lane must therefore still be able
        // to publish the ordinary physical gamepad mapping to the admitted
        // DS4 target; motion is only an optional contribution to that frame.
        inputCaptureRefreshRealStickSettings(true);
        initializeStartupInputGate();
        phase = "host-start";
        // HC target admission is serialized by the Coordinator tick. Do not
        // create the first target from the lifecycle-owner thread: it would
        // select a possibly stale UI snapshot before the BUS has taken its
        // canonical physical sample. The first BUS tick owns the complete
        // source -> target admission sequence, just like persona changes,
        // power rearm, and subsequent publication.
        appendNativeLifecycleLog("input-host-publication-deferred-to-bus", {
            {"reason", "await-first-coordinator-tick"},
            {"virtualTargetEnabled", g_realStickTest.virtualTargetEnabled},
            {"virtualTargetPersona", inputHostConfiguredPersona()},
            {"motionEnabled", g_realStickTest.motionEnabled},
            {"laneEnabled", g_realStickTest.enabled}
        });
        phase = "capture-loop";
        while (!g_inputCaptureStop.load(std::memory_order_acquire)) {
            onexX2OwnerTick();
            // The multimedia callback is the HC-equivalent TimerManager tick.
            // This wait is only a lifecycle-owner wait; it must not execute a
            // second input/update path after the callback has already run it.
            if (captureTimer) {
                const DWORD waitResult = WaitForSingleObject(captureTimer, 100);
                // Compatibility fallback only: if multimedia timers are not
                // available, the waitable timer has no callback, so the
                // lifecycle thread becomes the sole BUS dispatcher for that
                // fallback instance. Never run this branch for the normal
                // direct multimedia callback path.
                if (!multimediaTimer && waitResult == WAIT_OBJECT_0 &&
                    !g_inputCaptureStop.load(std::memory_order_acquire)) {
                    // Independent diagnostic scope; elapsed includes this fallback's lock wait.
                    const callbackCost::Scope tickCostScope(tickCostEnabled(), callbackCost::Source::waitableFallback,
                        [] { return tickCostEpochUs(std::chrono::steady_clock::now()); },
                        [] { return tickCostThreadCycleSample(); }, [] { return GetCurrentThreadId(); });
                    std::lock_guard<std::mutex> tickLock(g_inputCaptureBusTickMx);
                    inputCaptureBusTick();
                }
                // Host create/stop performs bounded process, pipe, driver and
                // PnP work. HC does not block its PrecisionTimer callback on
                // that lifecycle transaction; the lifecycle owner executes
                // the BUS-issued reconcile request after the tick returns.
                inputHostRunQueuedLifecycleWork();
                inputCaptureDrainQueuedSamples();
            } else {
                Sleep(kInputCaptureCoordinatorYieldMs);
                inputHostRunQueuedLifecycleWork();
                inputCaptureDrainQueuedSamples();
            }
            inputHostDisplayIdleAuditTick();
            observeStartupInputGate();
        }
        phase = "capture-shutdown";
        if (captureTimerId) {
            const MMRESULT timerKillReceipt = timeKillEvent(captureTimerId);
            g_inputTimerEvidence.killResult(timerEvidenceOwner, GetTickCount64(),
                reinterpret_cast<unsigned long long>(captureTimer), captureTimerId, timerKillReceipt);
            captureTimerId = 0;
        }
        // Match HC Snapshot.Release semantics at the lifecycle boundary: no
        // sensor/frame callback may still be inside the Coordinator when the
        // sensors, Host, and virtual target are disposed.
        {
            std::lock_guard<std::mutex> tickLock(g_inputCaptureBusTickMx);
        }
        inputCaptureShutdown();
        shutdownCompleted = true;
    } catch (const std::exception& error) {
        g_inputCaptureStop.store(true, std::memory_order_release);
        inputCaptureWorkerFault(phase, error.what());
        if (!shutdownCompleted) {
            if (captureTimerId) {
                const MMRESULT timerKillReceipt = timeKillEvent(captureTimerId);
                g_inputTimerEvidence.killResult(timerEvidenceOwner, GetTickCount64(),
                    reinterpret_cast<unsigned long long>(captureTimer), captureTimerId, timerKillReceipt);
                captureTimerId = 0;
            }
            {
                std::lock_guard<std::mutex> tickLock(g_inputCaptureBusTickMx);
            }
            try { inputCaptureShutdown(); shutdownCompleted = true; } catch (...) {}
            if (!shutdownCompleted) inputCaptureEmergencyCleanup();
        }
    } catch (...) {
        g_inputCaptureStop.store(true, std::memory_order_release);
        inputCaptureWorkerFault(phase, "non-standard exception");
        if (!shutdownCompleted) {
            if (captureTimerId) {
                const MMRESULT timerKillReceipt = timeKillEvent(captureTimerId);
                g_inputTimerEvidence.killResult(timerEvidenceOwner, GetTickCount64(),
                    reinterpret_cast<unsigned long long>(captureTimer), captureTimerId, timerKillReceipt);
                captureTimerId = 0;
            }
            {
                std::lock_guard<std::mutex> tickLock(g_inputCaptureBusTickMx);
            }
            try { inputCaptureShutdown(); shutdownCompleted = true; } catch (...) {}
            if (!shutdownCompleted) inputCaptureEmergencyCleanup();
        }
    }
    if (captureTimerId) {
        const MMRESULT timerKillReceipt = timeKillEvent(captureTimerId);
        g_inputTimerEvidence.killResult(timerEvidenceOwner, GetTickCount64(),
            reinterpret_cast<unsigned long long>(captureTimer), captureTimerId, timerKillReceipt);
    }
    if (captureTimer) {
        if (!multimediaTimer) CancelWaitableTimer(captureTimer);
        CloseHandle(captureTimer);
    }
    if (highResolutionTimer) timeEndPeriod(1);
    if (comInitialized) CoUninitialize();
    // Failure is terminal only after the worker's existing cleanup has run.
    publishStartupInputState(ymcc::StartupInputState::Failed, "capture-worker-stopped");
    return 0;
}

functions.inputCaptureStop:
static void inputCaptureStop() {
    g_inputCaptureStop.store(true, std::memory_order_release);
    if (g_machineIdentity.family == YmccFamily::LenovoLegionGo) legionMotionRevoke();
    if (g_inputCaptureThread) {
        const DWORD waitResult = WaitForSingleObject(g_inputCaptureThread, 2000);
        const DWORD waitError = waitResult == WAIT_FAILED ? GetLastError() : ERROR_SUCCESS;
        bool handleClosed = false;
        DWORD closeError = ERROR_SUCCESS;
        if (waitResult == WAIT_OBJECT_0) {
            handleClosed = CloseHandle(g_inputCaptureThread) != FALSE;
            if (handleClosed) g_inputCaptureThread = nullptr;
            else closeError = GetLastError();
        }
        try {
            appendNativeLifecycleLog("input-capture-worker-stop", {
                {"threadWaitBudgetMs", 2000}, {"waitResult", waitResult}, {"waitWin32", waitError},
                {"threadExitVerified", waitResult == WAIT_OBJECT_0},
                {"handleClosed", handleClosed}, {"closeWin32", closeError},
                {"ownerRetained", g_inputCaptureThread != nullptr}
            });
        } catch (...) {}
    }
    // 7.50 i2：DSU (ShockEmu) UDP 服务随 capture 停止（HC DSUServer 同生命周期）。
    dsu_stop();
    inputHostStop();
}
